INSERT OR REPLACE INTO documents (id, root_id, type_id, status, is_published, is_current_draft, slug, title, data, published_at, created_at, updated_at)
VALUES (
  'blog-post-trabzon-app-ru',
  'blog-post-trabzon-app-ru',
  'blog_post',
  'published',
  1,
  1,
  'trabzon-travel-guide-app-tourism-turkey-2026',
  'Путеводитель по Трабзону 2026: Достопримечательности Черноморского региона Турции, аренда авто и офлайн-приложение для путешествий',
  '{"title":"Путеводитель по Трабзону 2026: Достопримечательности Черноморского региона Турции, аренда авто и офлайн-приложение для путешествий","slug":"trabzon-travel-guide-app-tourism-turkey-2026","content":"\n    <div class=\"article-rich-text\" dir=\"ltr\" style=\"text-align: left; font-family: system-ui, -apple-system, sans-serif; line-height: 1.85; color: #1e293b;\">\n\n      <!-- Hero Banner Component -->\n      <div style=\"background: linear-gradient(135deg, #064e3b 0%, #047857 50%, #0284c7 100%); border-radius: 24px; padding: 40px 28px; color: #ffffff; margin-bottom: 36px; box-shadow: 0 16px 40px rgba(4, 120, 87, 0.3); text-align: center; position: relative; overflow: hidden;\">\n        <div style=\"display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; margin-bottom: 22px;\">\n          <span style=\"background: rgba(255, 255, 255, 0.2); backdrop-filter: blur(8px); padding: 6px 18px; border-radius: 30px; font-size: 0.88rem; font-weight: 800; letter-spacing: 0.5px; display: inline-block;\">\n            🌲 Путеводитель по Черноморскому побережью Турции 2026\n          </span>\n          <h1 style=\"color: #ffffff; font-size: clamp(1.6rem, 4vw, 2.35rem); font-weight: 900; margin: 4px 0 10px 0; line-height: 1.35;\">\n            Путеводитель по Трабзону 2026: Достопримечательности Черноморья, аренда авто и офлайн-приложение\n          </h1>\n          <p style=\"color: rgba(255, 255, 255, 0.95); font-size: 1.05rem; max-width: 780px; margin: 0 auto; line-height: 1.7;\">\n            Откройте для себя изумрудную сказку Турции: озеро Узунгёль, монастырь Сумела, альпийские луга Айдер, колоритную кухню и незаменимое приложение <strong>Trabzon Turkey Travel Guide</strong> с автономной GPS-навигацией без интернета.\n          </p>\n        </div>\n\n        <div style=\"display: flex; justify-content: center; gap: 14px; flex-wrap: wrap;\">\n          <a href=\"https://play.google.com/store/apps/details?id=com.trabzon.turkey.travel.guide\" target=\"_blank\" rel=\"noopener\" style=\"background: #ffffff; color: #064e3b !important; padding: 14px 28px; border-radius: 30px; font-weight: 900; font-size: 1.02rem; text-decoration: none; display: inline-flex; align-items: center; gap: 10px; box-shadow: 0 8px 24px rgba(0,0,0,0.2);\">\n            <i class=\"fa-brands fa-google-play\" style=\"font-size: 1.3rem; color: #047857;\"></i>\n            <span>Скачать Trabzon Guide на Google Play</span>\n          </a>\n        </div>\n      </div>\n\n      <!-- App Showcase Image 1 -->\n      <figure style=\"margin: 36px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/01_trabzon_app_hero_mockup.jpg\" alt=\"Мобильное приложение Trabzon Turkey Travel Guide на фоне озера Узунгёль\" style=\"width: 100%; max-height: 520px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          📱 Интерфейс приложения Trabzon Turkey Travel Guide с офлайн-картами и каталогом природных достопримечательностей\n        </figcaption>\n      </figure>\n\n      <p style=\"font-size: 1.12rem; line-height: 1.9; margin-bottom: 24px;\">\n        Черноморский регион Турции (Karadeniz) и его жемчужина — провинция <strong>Трабзон</strong> — кардинально отличаются от привычных средиземноморских курортов. Вместо палящего зноя здесь вас встретят реликтовые хвойные леса, каскадные горные реки, бурные водопады, облака, плывущие прямо под ногами, и тысячелетние византийские святыни, высеченные в отвесных скалах.\n      </p>\n\n      <h2 style=\"color: #064e3b; font-size: 1.65rem; font-weight: 800; margin: 38px 0 18px 0; border-bottom: 2px solid #e2e8f0; padding-bottom: 10px;\">\n        1. Главные природные и исторические сокровища Трабзона\n      </h2>\n\n      <h3 style=\"color: #047857; font-size: 1.35rem; font-weight: 700; margin: 26px 0 12px 0;\">\n        Озеро Узунгёль (Uzungöl) — Символ Черноморья\n      </h3>\n      <p style=\"font-size: 1.05rem; line-height: 1.85; margin-bottom: 20px;\">\n        Горное озеро Узунгёль, расположенное на высоте 1090 метров над уровнем моря в ущелье реки Халдизен, обрамлено густыми еловыми лесами и белоснежным силуэтом мечети с двумя минаретами. Здесь путешественники наслаждаются пешими прогулками вокруг озера, катанием на катамаранах и отдыхом в уютных деревянных шале.\n      </p>\n\n      <!-- Real Image 2 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/02_uzungol_lake_real_view.jpg\" alt=\"Реальный панорамный вид озера Узунгёль в Трабзоне с мечетью и горами\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          🏞️ Панорама озера Узунгёль в утренней дымке — идеальное место для семейного отдыха и фотосъемки\n        </figcaption>\n      </figure>\n\n      <h3 style=\"color: #047857; font-size: 1.35rem; font-weight: 700; margin: 26px 0 12px 0;\">\n        Скальный монастырь Панагия Сумела (Sümela Manastırı)\n      </h3>\n      <p style=\"font-size: 1.05rem; line-height: 1.85; margin-bottom: 20px;\">\n        Основанный в IV веке нашей эры, монастырь Сумела висит на отвесном утесе на высоте свыше 300 метров над долиной Алтындере в районе Мачка. Отреставрированные древние фрески, каменная часовня и головокружительный вид на ущелье оставляют неизгладимое впечатление.\n      </p>\n\n      <!-- Real Image 3 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/03_sumela_monastery_cliff_real.jpg\" alt=\"Скальный монастырь Сумела в Трабзоне на отвесном утесе\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          🏛️ Монастырь Сумела в долине Алтындере — шедевр средневековой архитектуры, вписанный в скалу\n        </figcaption>\n      </figure>\n\n      <h3 style=\"color: #047857; font-size: 1.35rem; font-weight: 700; margin: 26px 0 12px 0;\">\n        Высокогорное плато Айдер (Ayder Yaylası) и долина реки Фыртына (Fırtına Vadisi)\n      </h3>\n      <p style=\"font-size: 1.05rem; line-height: 1.85; margin-bottom: 20px;\">\n        Плато Айдер в соседней провинции Ризе славится термальными минеральными источниками, деревянными домиками и водопадом Гелин Тюлю (Gelin Tülü). По пути к плато вдоль реки Фыртына обязательно остановитесь у османских каменных арочных мостов, попробуйте безопасный рафтинг и посетите старинную крепость Зилькале (Zilkale).\n      </p>\n\n      <!-- Real Image 4 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/04_ayder_plateau_waterfalls_real.jpg\" alt=\"Плато Айдер в Ризе с деревянными шале и водопадами\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          ⛰️ Высокогорное плато Айдер — альпийские луга, водопады и целебный горный воздух\n        </figcaption>\n      </figure>\n\n      <!-- Real Image 5 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/05_boztepe_trabzon_sunset_real.jpg\" alt=\"Панорамный закат с холма Бозтепе над Трабзоном и Черным морем\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          🌅 Холм Бозтепе в центре Трабзона: лучший закатный вид на Черное море с чашечкой аутентичного чая\n        </figcaption>\n      </figure>\n\n      <!-- Real Image 6 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/06_hamsikoy_nature_valley_real.jpg\" alt=\"Деревня Хамсикёй в долине Зигана с зелеными пастбищами\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          🍮 Деревня Хамсикёй у перевала Зигана — родина знаменитого запеченного рисового пудинга (Сютлач)\n        </figcaption>\n      </figure>\n\n      <h2 style=\"color: #064e3b; font-size: 1.65rem; font-weight: 800; margin: 38px 0 18px 0; border-bottom: 2px solid #e2e8f0; padding-bottom: 10px;\">\n        2. Аренда авто в Трабзоне и офлайн-навигация без интернета\n      </h2>\n      <p style=\"font-size: 1.05rem; line-height: 1.85; margin-bottom: 20px;\">\n        Путешествие по Черноморскому побережью Турции раскрывается во всей красе именно за рулем автомобиля. Вы не привязаны к жесткому графику экскурсионных автобусов и можете встречать рассветы на высокогорных плато.\n      </p>\n\n      <!-- Real Image 7 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/07_car_rental_roadtrip_offline_gps.jpg\" alt=\"Аренда автомобиля в Трабзоне и офлайн GPS-навигация в горах\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          🚗 Поездка по горным серпантинам Трабзона с офлайн GPS-навигатором приложения\n        </figcaption>\n      </figure>\n\n      <div style=\"background: #f8fafc; border-left: 4px solid #047857; padding: 20px; border-radius: 12px; margin: 24px 0;\">\n        <h4 style=\"margin: 0 0 10px 0; color: #064e3b; font-size: 1.15rem;\">Советы по автопутешествию:</h4>\n        <ul style=\"margin: 0; padding-left: 20px; line-height: 1.8; color: #475569;\">\n          <li>Бронируйте авто заранее, особенно в летний сезон (июнь–август), забирая машину прямо в терминале аэропорта Трабзона.</li>\n          <li>Для поездок к обычным достопримечательностям (Узунгёль, Сумела, Айдер) подойдет стандартный седан. Для поездок на плато Покут или Сал потребуется кроссовер или 4x4.</li>\n          <li>Следите за ценами на топливо на нашей странице <a href=\"/ru/akaryakit-fiyatlari\" style=\"color: #047857; font-weight: 700;\">цены на бензин и дизель в Турции</a>.</li>\n          <li>Проверяйте актуальный <a href=\"/ru/currency-prices\" style=\"color: #047857; font-weight: 700;\">курс турецкой лиры</a> для оптимального обмена валюты.</li>\n        </ul>\n      </div>\n\n      <!-- App Download Banner Image 8 -->\n      <figure style=\"margin: 36px 0; text-align: center;\">\n        <a href=\"https://play.google.com/store/apps/details?id=com.trabzon.turkey.travel.guide\" target=\"_blank\" rel=\"noopener\">\n          <img src=\"/public/images/trabzon-app/08_google_play_download_trabzon_app.jpg\" alt=\"Скачать приложение Trabzon Turkey Travel Guide на Google Play\" style=\"width: 100%; max-height: 480px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        </a>\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          📲 Бесплатное приложение Trabzon Turkey Travel Guide на Google Play с рейтингом 4.9 ★\n        </figcaption>\n      </figure>\n\n      <!-- CTA Box -->\n      <div style=\"background: linear-gradient(135deg, #0f172a 0%, #064e3b 100%); border-radius: 20px; padding: 34px 26px; color: white; text-align: center; margin: 40px 0;\">\n        <h3 style=\"color: white; font-size: 1.5rem; font-weight: 800; margin: 0 0 12px 0;\">\n          Готовы к незабываемому путешествию в Трабзон?\n        </h3>\n        <p style=\"color: #e2e8f0; font-size: 1.05rem; max-width: 650px; margin: 0 auto 24px auto; line-height: 1.7;\">\n          Установите приложение <strong>Trabzon Turkey Travel Guide</strong> прямо сейчас из Google Play и путешествуйте с точными офлайн-картами, проверенными маршрутами и секретными локациями!\n        </p>\n        <a href=\"https://play.google.com/store/apps/details?id=com.trabzon.turkey.travel.guide\" target=\"_blank\" rel=\"noopener\" style=\"background: #10b981; color: white !important; padding: 14px 32px; border-radius: 30px; font-weight: 800; text-decoration: none; display: inline-flex; align-items: center; gap: 10px; box-shadow: 0 6px 20px rgba(16, 185, 129, 0.4);\">\n          <i class=\"fa-brands fa-google-play\"></i>\n          <span>Установить бесплатно на Android</span>\n        </a>\n      </div>\n\n    </div>\n  "}',
  1791541436483,
  1791541436483,
  1791541436483
);

INSERT OR REPLACE INTO documents (id, root_id, type_id, status, is_published, is_current_draft, slug, title, data, published_at, created_at, updated_at)
VALUES (
  'blog-post-trabzon-app-fa',
  'blog-post-trabzon-app-fa',
  'blog_post',
  'published',
  1,
  1,
  'trabzon-travel-guide-app-tourism-turkey-2026',
  'راهنمای سفر به ترابزون و شمال ترکیه ۲۰۲۶: جاهای دیدنی، دریاچه اوزون گل، اجاره خودرو و اپلیکیشن آفلاین',
  '{"title":"راهنمای سفر به ترابزون و شمال ترکیه ۲۰۲۶: جاهای دیدنی، دریاچه اوزون گل، اجاره خودرو و اپلیکیشن آفلاین","slug":"trabzon-travel-guide-app-tourism-turkey-2026","content":"\n    <div class=\"article-rich-text\" dir=\"rtl\" style=\"text-align: right; font-family: system-ui, -apple-system, sans-serif; line-height: 1.9; color: #1e293b;\">\n\n      <!-- Hero Banner Component -->\n      <div style=\"background: linear-gradient(135deg, #064e3b 0%, #047857 50%, #0284c7 100%); border-radius: 24px; padding: 40px 28px; color: #ffffff; margin-bottom: 36px; box-shadow: 0 16px 40px rgba(4, 120, 87, 0.3); text-align: center; position: relative; overflow: hidden;\">\n        <div style=\"display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; margin-bottom: 22px;\">\n          <span style=\"background: rgba(255, 255, 255, 0.2); backdrop-filter: blur(8px); padding: 6px 18px; border-radius: 30px; font-size: 0.88rem; font-weight: 800; letter-spacing: 0.5px; display: inline-block;\">\n            🌲 راهنمای جامع گردشگری شمال ترکیه و سواحل دریای سیاه ۲۰۲۶\n          </span>\n          <h1 style=\"color: #ffffff; font-size: clamp(1.6rem, 4vw, 2.35rem); font-weight: 900; margin: 4px 0 10px 0; line-height: 1.35;\">\n            راهنمای سفر به ترابزون ۲۰۲۶: بهشت گمشده ترکیه، اوزون گل، سوملا و اپلیکیشن آفلاین\n          </h1>\n          <p style=\"color: rgba(255, 255, 255, 0.95); font-size: 1.05rem; max-width: 780px; margin: 0 auto; line-height: 1.7;\">\n            کشف طبیعت رویایی سواحل دریای سیاه، جنگل‌های مه‌آلود، آبشارهای خروشان، کلبه‌های چوبی در کنار رودخانه و معرفی اپلیکیشن ضروری <strong>Trabzon Turkey Travel Guide</strong> با مسیریاب آفلاین در گوگل پلی.\n          </p>\n        </div>\n\n        <div style=\"display: flex; justify-content: center; gap: 14px; flex-wrap: wrap;\">\n          <a href=\"https://play.google.com/store/apps/details?id=com.trabzon.turkey.travel.guide\" target=\"_blank\" rel=\"noopener\" style=\"background: #ffffff; color: #064e3b !important; padding: 14px 28px; border-radius: 30px; font-weight: 900; font-size: 1.02rem; text-decoration: none; display: inline-flex; align-items: center; gap: 10px; box-shadow: 0 8px 24px rgba(0,0,0,0.2);\">\n            <i class=\"fa-brands fa-google-play\" style=\"font-size: 1.3rem; color: #047857;\"></i>\n            <span>دانلود رایگان اپلیکیشن از Google Play</span>\n          </a>\n        </div>\n      </div>\n\n      <!-- App Mockup 1 -->\n      <figure style=\"margin: 36px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/01_trabzon_app_hero_mockup.jpg\" alt=\"اپلیکیشن راهنمای سفر به ترابزون و اوزون گل روی گوشی اندروید\" style=\"width: 100%; max-height: 520px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          📱 نمای اپلیکیشن Trabzon Turkey Travel Guide با امکانات نقشه آفلاین و مسیریابی بدون اینترنت\n        </figcaption>\n      </figure>\n\n      <p style=\"font-size: 1.12rem; line-height: 1.9; margin-bottom: 24px;\">\n        منطقه کارادنیز (دریای سیاه) و در رأس آن شهر تاریخی و سرسبز <strong>ترابزون</strong>، یکی از محبوب‌ترین مقاصد گردشگری برای مسافران اهل طبیعت است. هوای معتدل کوهستانی، اقیانوس ابرها، مزارع سرسبز چای و فندق و مردمان مهمان‌نواز، این منطقه را به بهشتی بی‌بدیل تبدیل کرده است.\n      </p>\n\n      <h2 style=\"color: #064e3b; font-size: 1.65rem; font-weight: 800; margin: 38px 0 18px 0; border-bottom: 2px solid #e2e8f0; padding-bottom: 10px;\">\n        ۱. مهم‌ترین جاذبه‌های دیدنی ترابزون و اطراف آن\n      </h2>\n\n      <h3 style=\"color: #047857; font-size: 1.35rem; font-weight: 700; margin: 26px 0 12px 0;\">\n        دریاچه اوزون‌گول (Uzungöl)؛ نگین سبز شمال ترکیه\n      </h3>\n      <p style=\"font-size: 1.05rem; line-height: 1.85; margin-bottom: 20px;\">\n        دریاچه اوزون‌گول در میان کوه‌های سربه فلک کشیده و جنگل‌های سرسبز صنوبر واقع شده است. بازتاب مناره‌های سفید مسجد در آب زلال دریاچه و قدم زدن در مسیرهای پیاده‌روی دور دریاچه، تجربه‌ای فراموش‌نشدنی را برای هر گردشگری رقم می‌زند.\n      </p>\n\n      <!-- Real Image 2 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/02_uzungol_lake_real_view.jpg\" alt=\"منظره واقعی دریاچه اوزون گل در ترابزون ترکیه\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          🏞️ چشم‌انداز آرامش‌بخش دریاچه اوزون‌گول و مسجد تاریخی آن در میان کوهستان‌های سرسبز\n        </figcaption>\n      </figure>\n\n      <h3 style=\"color: #047857; font-size: 1.35rem; font-weight: 700; margin: 26px 0 12px 0;\">\n        صومعه صخره‌ای سوملا (Sümela Manastırı)\n      </h3>\n      <p style=\"font-size: 1.05rem; line-height: 1.85; margin-bottom: 20px;\">\n        این شاهکار معماری باستانی که قدمت آن به قرن چهارم میلادی بازمی‌گردد، در دل صخره‌های عمودی دره آلتین‌دره در منطقه ماچکا ساخته شده است. نقاشی‌های دیواری باستانی و چشم‌انداز خیره‌کننده دره، آن را به یکی از شگفتی‌های تاریخی ترکیه تبدیل کرده است.\n      </p>\n\n      <!-- Real Image 3 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/03_sumela_monastery_cliff_real.jpg\" alt=\"صومعه تاریخی سوملا ترابزون معلق بر فراز دره آلتین دره\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          🏛️ صومعه سوملا؛ معجزه معماری صخره‌ای در ارتفاعات ترابزون\n        </figcaption>\n      </figure>\n\n      <h3 style=\"color: #047857; font-size: 1.35rem; font-weight: 700; margin: 26px 0 12px 0;\">\n        ییلاق آیدر (Ayder Yaylası) و دره فیرتینا (Fırtına Vadisi)\n      </h3>\n      <p style=\"font-size: 1.05rem; line-height: 1.85; margin-bottom: 20px;\">\n        ییلاق معروف آیدر در استان ریزه، چشمه‌های آب گرم معدنی، آبشار گلین تولو، پل‌های سنگی عثمانی و هیجان قایق‌سواری آرام (رفتینگ) در رودخانه خروشان فیرتینا را در خود جای داده است.\n      </p>\n\n      <!-- Real Image 4 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/04_ayder_plateau_waterfalls_real.jpg\" alt=\"ییلاق سرسبز آیدر ریزه با کلبه های چوبی و آبشارها\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          ⛰️ ییلاق آیدر؛ هوای پاک کوهستانی، آبشارهای زیبا و کلبه‌های چوبی سنتی\n        </figcaption>\n      </figure>\n\n      <!-- Real Image 5 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/05_boztepe_trabzon_sunset_real.jpg\" alt=\"غروب تماشایی از تپه بوزتپه ترابزون مشرف به دریای سیاه\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          🌅 بام ترابزون (بوزتپه): تماشای غروب خورشید بر فراز دریای سیاه همراه با یک فنجان چای اصیل ترکی\n        </figcaption>\n      </figure>\n\n      <!-- Real Image 6 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/06_hamsikoy_nature_valley_real.jpg\" alt=\"روستای زیبای همسی کوی ترابزون در دره زیگانا\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          🍮 روستای همسی‌کوی در گردنه زیگانا؛ مهد معروف‌ترین شیربرنج تنوری ترکیه (سوتلاچ)\n        </figcaption>\n      </figure>\n\n      <h2 style=\"color: #064e3b; font-size: 1.65rem; font-weight: 800; margin: 38px 0 18px 0; border-bottom: 2px solid #e2e8f0; padding-bottom: 10px;\">\n        ۲. راهنمای اجاره خودرو و رانندگی در شمال ترکیه با نقشه آفلاین\n      </h2>\n      <p style=\"font-size: 1.05rem; line-height: 1.85; margin-bottom: 20px;\">\n        رانندگی در جاده‌های سرسبز ترابزون و ریزه لذت سفر را دوچندان می‌کند. با داشتن خودرو می‌توانید در هر زمان که مایل بودید، به ییلاقات مرتفع سفر کنید و هزینه‌های رفت‌وآمد خود را مدیریت نمایید.\n      </p>\n\n      <!-- Real Image 7 -->\n      <figure style=\"margin: 32px 0; text-align: center;\">\n        <img src=\"/public/images/trabzon-app/07_car_rental_roadtrip_offline_gps.jpg\" alt=\"اجاره خودرو در ترابزون و رانندگی با نقشه آفلاین GPS\" style=\"width: 100%; max-height: 500px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          🚗 تجربه رانندگی جاده‌ای در کوهستان‌های ترابزون با دستیار مسیریابی آفلاین\n        </figcaption>\n      </figure>\n\n      <div style=\"background: #f8fafc; border-right: 4px solid #047857; padding: 20px; border-radius: 12px; margin: 24px 0;\">\n        <h4 style=\"margin: 0 0 10px 0; color: #064e3b; font-size: 1.15rem;\">نکات مهم برای رانندگی و سفر:</h4>\n        <ul style=\"margin: 0; padding-right: 20px; line-height: 1.8; color: #475569;\">\n          <li>خودروی خود را از قبل در فرودگاه ترابزون رزرو کنید تا با بهترین قیمت و بیمه کامل تحویل بگیرید.</li>\n          <li>برای مسیرهای استاندارد (اوزون گل، سوملا، آیدر) یک سواری معمولی کافی است؛ اما برای ارتفاعات بوکوت به خودروی شاسی‌بلند (۴x۴) نیاز خواهید داشت.</li>\n          <li>برای آگاهی از هزینه‌های سفر، صفحه <a href=\"/fa/currency-prices\" style=\"color: #047857; font-weight: 700;\">قیمت لحظه‌ای لیر ترکیه</a> و <a href=\"/fa/akaryakit-fiyatlari\" style=\"color: #047857; font-weight: 700;\">قیمت بنزین در ترکیه</a> را بررسی کنید.</li>\n        </ul>\n      </div>\n\n      <!-- App Download Banner Image 8 -->\n      <figure style=\"margin: 36px 0; text-align: center;\">\n        <a href=\"https://play.google.com/store/apps/details?id=com.trabzon.turkey.travel.guide\" target=\"_blank\" rel=\"noopener\">\n          <img src=\"/public/images/trabzon-app/08_google_play_download_trabzon_app.jpg\" alt=\"دانلود اپلیکیشن راهنمای ترابزون در گوگل پلی\" style=\"width: 100%; max-height: 480px; object-fit: cover; border-radius: 18px; box-shadow: 0 12px 30px rgba(0,0,0,0.15);\" loading=\"lazy\">\n        </a>\n        <figcaption style=\"margin-top: 12px; font-size: 0.9rem; color: #64748b; font-weight: 600;\">\n          📲 اپلیکیشن رایگان Trabzon Turkey Travel Guide در Google Play با امتیاز ۴.۹ از کاربران\n        </figcaption>\n      </figure>\n\n      <!-- CTA Box -->\n      <div style=\"background: linear-gradient(135deg, #0f172a 0%, #064e3b 100%); border-radius: 20px; padding: 34px 26px; color: white; text-align: center; margin: 40px 0;\">\n        <h3 style=\"color: white; font-size: 1.5rem; font-weight: 800; margin: 0 0 12px 0;\">\n          آماده سفری شگفت‌انگیز به ترابزون و شمال ترکیه هستید؟\n        </h3>\n        <p style=\"color: #e2e8f0; font-size: 1.05rem; max-width: 650px; margin: 0 auto 24px auto; line-height: 1.7;\">\n          همین حالا اپلیکیشن <strong>Trabzon Turkey Travel Guide</strong> را به صورت کاملاً رایگان از گوگل پلی نصب کنید و با نقشه‌های بدون نیاز به اینترنت، با خیالی آسوده سفر کنید.\n        </p>\n        <a href=\"https://play.google.com/store/apps/details?id=com.trabzon.turkey.travel.guide\" target=\"_blank\" rel=\"noopener\" style=\"background: #10b981; color: white !important; padding: 14px 32px; border-radius: 30px; font-weight: 800; text-decoration: none; display: inline-flex; align-items: center; gap: 10px; box-shadow: 0 6px 20px rgba(16, 185, 129, 0.4);\">\n          <i class=\"fa-brands fa-google-play\"></i>\n          <span>نصب رایگان برای اندروید از Google Play</span>\n        </a>\n      </div>\n\n    </div>\n  "}',
  1791541436483,
  1791541436483,
  1791541436483
);

INSERT OR REPLACE INTO documents (id, root_id, type_id, status, is_published, is_current_draft, slug, title, data, published_at, created_at, updated_at)
VALUES (
  'blog-post-trabzon-app-ur',
  'blog-post-trabzon-app-ur',
